let n = 300;
let delta;
let factor;


function setup(){
createCanvas(700, 680);
delta = 2*PI/n;
frameRate(15);
}
var factor = 1;
function draw(){
//factor = 32*(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width;
//factor = 1;	
background(50);
translate(width/2, height/2);
stroke(10);
strokeWeight(3);
noFill();
ellipse(0,0,44,150);
stroke(40,150,255*abs(sin(factor*PI/100)));
strokeWeight(5);
for(i = 0; i < n; i ++){
   point(250*cos(i*delta), 300*sin(i*delta));
   strokeWeight(1);
   line(300*cos(i*delta), 300*sin(i*delta), 100*cos(factor*i*delta), 50*sin(factor*i*delta));
  }

factor = factor + 13;
}

